import { useEffect, useState } from 'react';
import { ClipboardCheck, RefreshCw } from 'lucide-react';
import { api } from '../lib/api';
import NewHereHint from './NewHereHint';
import { EmptyState } from './EmptyState';
import type { ForecastScoreboard } from '../types';

/**
 * Forecast scoreboard (T125).
 *
 * The public accountability ledger: every pre-registered prediction band,
 * the numeric range committed before the data existed, and the mechanical
 * verdict after scoring. Misses render in the same table as hits — that's
 * the whole epistemology of the project in one view.
 *
 * Data comes from forecast-scoreboard.json, generated mechanically from the
 * forecast-track-record ledger by backend/scripts/build_forecast_scoreboard.py
 * (never hand-edited: if the table and the panel disagree, the table wins).
 */

const STATUS_STYLE: Record<string, { label: string; cls: string }> = {
  pass: { label: 'PASS', cls: 'bg-emerald-100 text-emerald-800' },
  fail_low: { label: 'FAIL-LOW', cls: 'bg-rose-100 text-rose-800' },
  fail_high: { label: 'FAIL-HIGH', cls: 'bg-rose-100 text-rose-800' },
  unmeasurable: { label: 'UNMEASURABLE', cls: 'bg-amber-100 text-amber-800' },
  pending: { label: 'pending', cls: 'bg-border text-text-muted' },
  other: { label: 'see ledger', cls: 'bg-border text-text-muted' },
};

function Chip({ status }: { status: string }) {
  const s = STATUS_STYLE[status] ?? STATUS_STYLE.other;
  return (
    <span className={`inline-block rounded px-1.5 py-0.5 text-[11px] font-semibold tracking-wide ${s.cls}`}>
      {s.label}
    </span>
  );
}

export default function ForecastScoreboardPanel() {
  const [data, setData] = useState<ForecastScoreboard | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    setError(null);
    try {
      setData(await api.forecastScoreboard());
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, []);

  const scored = data?.forecasts.flatMap((f) => f.bands).filter((b) => b.status !== 'pending') ?? [];
  const passes = scored.filter((b) => b.status === 'pass').length;

  return (
    <div className="space-y-3">
      <div className="flex items-start justify-between">
        <div>
          <h2 className="flex items-center gap-2 text-lg font-semibold text-text-primary">
            <ClipboardCheck className="h-5 w-5 text-emerald-500" aria-hidden />
            Forecast scoreboard
          </h2>
          <p className="text-sm text-text-muted">
            Every pre-registered prediction and its mechanical verdict — misses published
            alongside hits, always.
          </p>
        </div>
        <button
          onClick={() => void load()}
          className="rounded p-1 text-text-muted hover:text-text-primary"
          aria-label="Reload"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {loading && (
        <div role="status" aria-live="polite" className="p-6 text-sm text-text-muted">
          Loading the ledger…
        </div>
      )}
      {error && (
        <div role="alert" className="rounded-xl border border-rose-300 bg-rose-50 p-3 text-sm text-rose-700">
          {error}
        </div>
      )}

      {data && (
        <>
          <div className="mt-3">
            <NewHereHint text="Predictions are committed publicly before the data exists, then graded by a mechanical script — never by judgment calls. The misses stay published: that is what makes the hits mean something." />
          </div>

          {data.rules.length > 0 && (
            <ol className="rounded-xl border border-border bg-card/50 p-3 text-xs text-text-muted">
              {data.rules.map((r, i) => (
                <li key={i} className={i > 0 ? 'mt-1' : ''}>
                  {i + 1}. {r}
                </li>
              ))}
            </ol>
          )}

          {data.forecasts.map((f) => (
            <div key={f.title} className="overflow-hidden rounded-xl border border-border">
              <div className="flex flex-wrap items-baseline justify-between gap-2 bg-card/70 px-3 py-2">
                <h3 className="text-sm font-semibold text-text-primary">{f.title}</h3>
                <div className="text-xs text-text-muted">
                  registered {f.registered || '?'}
                  {scored.length > 0 && f.tally.pass + f.tally.fail + f.tally.unmeasurable > 0 && (
                    <> · {f.tally.pass} pass · {f.tally.fail} fail · {f.tally.unmeasurable} unmeasurable</>
                  )}
                </div>
              </div>
              <table className="w-full text-sm">
                <thead className="bg-card/40 text-left text-xs uppercase tracking-wide text-text-muted">
                  <tr>
                    <th className="px-3 py-1.5">Band</th>
                    <th className="px-3 py-1.5">Prediction</th>
                    <th className="px-3 py-1.5">Verdict</th>
                  </tr>
                </thead>
                <tbody>
                  {f.bands.map((b, i) => (
                    <tr key={i} className="border-t border-border">
                      <td className="px-3 py-1.5 text-text-primary">{b.band}</td>
                      <td className="px-3 py-1.5 tabular-nums text-text-muted">{b.prediction}</td>
                      <td className="px-3 py-1.5">
                        <Chip status={b.status} />
                        {b.status === 'unmeasurable' && (
                          <span className="ml-2 text-xs text-text-muted">{b.verdict.replace(/^.*UNMEASURABLE\s*—?\s*/i, '')}</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ))}

          <p className="text-xs text-text-muted">
            Scored so far: {scored.length} bands, {passes} pass — full ledger with citations:{' '}
            <a
              className="underline hover:text-text-primary"
              href="/miway-findings/docs/findings/forecast-track-record.html"
              target="_blank"
              rel="noreferrer"
            >
              forecast-track-record
            </a>. Generated {new Date(data.generated_at).toLocaleDateString()}.
          </p>
        </>
      )}

      {!loading && !error && !data && (
        <EmptyState reason="The scoreboard endpoint returned nothing." onRetry={() => void load()} />
      )}
    </div>
  );
}
